create function public.cineo_pin_attempt(actor uuid,passed boolean) returns void language plpgsql security invoker set search_path='' as $$declare p public.cineo_parental;begin select * into p from public.cineo_parental where user_id=actor for update;if not found then raise exception 'PIN inexistente';end if;if p.locked_until>now() then raise exception 'PIN bloqueado por 15 minutos';end if;if passed then update public.cineo_parental set failures=0,locked_until=null where user_id=actor;else update public.cineo_parental set failures=failures+1,locked_until=case when failures>=4 then now()+interval '15 minutes' else null end where user_id=actor;end if;end$$;revoke all on function public.cineo_pin_attempt(uuid,boolean) from public,anon,authenticated;grant execute on function public.cineo_pin_attempt(uuid,boolean) to service_role;
